mapper.select:
SELECT u.user_id AS userId, la.login_id AS loginId, #{tenantCode} AS tenantCode, u.user_nm AS userNm, u.email_addr AS emailAddr, COALESCE(d.department_nm, '') AS departmentNm, COALESCE( ( SELECT r1.role_code FROM tb_login_account_role lar1 JOIN tb_role r1 ON r1.role_id = lar1.role_id WHERE lar1.login_id = la.login_id ORDER BY CASE WHEN r1.role_code = 'PLATFORM_ADMIN' THEN 1 WHEN r1.role_code = 'TENANT_ADMIN' THEN 2 WHEN r1.role_code = 'TENANT_USER' THEN 3 ELSE 99 END, r1.role_id LIMIT 1 ), '' ) AS roleCode, CASE WHEN COALESCE(u.use_at, 'N') = 'Y' AND COALESCE(la.use_at, 'N') = 'Y' THEN TRUE ELSE FALSE END AS active, la.login_code AS loginCode, la.profile_image AS profileImage, la.stamp_image AS signatureImage, la.stamp_image AS stampImage, COALESCE(u.use_at, 'N') AS useAt, COALESCE(la.use_at, 'N') AS loginUseAt FROM tb_user u JOIN tb_login_account la ON la.login_id = u.login_id LEFT JOIN tb_department d ON d.department_id = u.department_id WHERE 1 = 1
AND u.tenant_id = #{tenantId}
ORDER BY u.created_at DESC, u.user_id DESC

SELECT * FROM ( SELECT u.user_id AS userId, la.login_id AS loginId, #{tenantCode} AS tenantCode, u.user_nm AS userNm, u.email_addr AS emailAddr, COALESCE(d.department_nm, '') AS departmentNm, COALESCE( ( SELECT r1.role_code FROM tb_login_account_role lar1 JOIN tb_role r1 ON r1.role_id = lar1.role_id WHERE lar1.login_id = la.login_id ORDER BY CASE WHEN r1.role_code = 'PLATFORM_ADMIN' THEN 1 WHEN r1.role_code = 'TENANT_ADMIN' THEN 2 WHEN r1.role_code = 'TENANT_USER' THEN 3 ELSE 99 END, r1.role_id LIMIT 1 ), '' ) AS roleCode, CASE WHEN COALESCE(u.use_at, 'N') = 'Y' AND COALESCE(la.use_at, 'N') = 'Y' THEN TRUE ELSE FALSE END AS active, la.login_code AS loginCode, la.profile_image AS profileImage, la.stamp_image AS signatureImage, la.stamp_image AS stampImage, COALESCE(u.use_at, 'N') AS useAt, COALESCE(la.use_at, 'N') AS loginUseAt, ROW_NUMBER() OVER (ORDER BY u.created_at DESC, u.user_id DESC) AS rn FROM tb_user u JOIN tb_login_account la ON la.login_id = u.login_id LEFT JOIN tb_department d ON d.department_id = u.department_id WHERE 1 = 1
AND u.tenant_id = #{tenantId}
AND ( LOWER(u.user_nm) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(u.email_addr) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(COALESCE(d.department_nm, '')) LIKE '%' || LOWER(#{keyword}) || '%' )
AND COALESCE(u.use_at, 'N') = 'Y' AND COALESCE(la.use_at, 'N') = 'Y'
AND NOT (COALESCE(u.use_at, 'N') = 'Y' AND COALESCE(la.use_at, 'N') = 'Y')
) user_query WHERE rn BETWEEN #{firstIndex} AND #{lastIndex} ORDER BY rn

SELECT department_id
FROM tb_department
WHERE tenant_id = #{tenantId}
  AND department_nm = #{departmentNm}
ORDER BY department_id
LIMIT 1

SELECT login_id
FROM tb_user
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
LIMIT 1

SELECT login_id
FROM tb_login_account
WHERE tenant_id = #{tenantId}
  AND login_code = #{loginCode}
LIMIT 1

SELECT user_id
FROM tb_user
WHERE tenant_id = #{tenantId}
  AND login_id = #{loginId}
LIMIT 1

SELECT role_id
FROM tb_role
WHERE tenant_id = #{tenantId}
  AND role_code = #{roleCode}
LIMIT 1

choose.otherwise:
UPDATE tb_user
SET use_at = #{useAt},
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
